/// The logo of a tool (claude, copilot, cli, vscode). A VS Code chat shows
/// Copilot's with VS Code's as a badge.
class ToolLogo extends StatelessWidget {
  const ToolLogo(this.tool, {super.key, this.size = 18});

  final String tool;
  final double size;

  static Widget _svg(String s, double size, Color? color) => SvgPicture.string(s,
      width: size, height: size, colorFilter: color == null ? null : ColorFilter.mode(color, BlendMode.srcIn));

  static Widget _of(String tool, double size) => switch (tool) {
        'copilot' => _svg(_copilot, size, C.text),
        'cli' => Icon(Icons.terminal_rounded, size: size, color: C.dim),
        _ => _svg(_claude, size, claudeOrange),
      };

  @override
  Widget build(BuildContext context) {
    if (tool != 'vscode') return SizedBox.square(dimension: size, child: Center(child: _of(tool, size)));
    final b = (size * .58).roundToDouble();
    return SizedBox.square(
      dimension: size,
      child: Stack(clipBehavior: Clip.none, children: [
        _of('copilot', size),
        Positioned(
          right: -b * .35,
          bottom: -b * .3,
          child: Container(
            padding: const EdgeInsets.all(1.2),
            decoration: BoxDecoration(color: C.bg, borderRadius: BorderRadius.circular(b * .3)),
            child: _svg(_vscode, b, null),
          ),
        ),
      ]),
    );
  }
}
